import{_ as o,o as t,c as e,ag as i}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-10-23（物理 / 分子机器 / 纳米机电）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/physics/science-daily-2026-10-23-physics.md","filePath":"topics/physics/science-daily-2026-10-23-physics.md"}'),c={name:"topics/physics/science-daily-2026-10-23-physics.md"};function n(r,s,a,l,d,g){return t(),e("div",null,[...s[0]||(s[0]=[i('<h1 id="科学日报-·-2026-10-23-物理-分子机器-纳米机电" tabindex="-1">科学日报 · 2026-10-23（物理 / 分子机器 / 纳米机电） <a class="header-anchor" href="#科学日报-·-2026-10-23-物理-分子机器-纳米机电" aria-label="Permalink to &quot;科学日报 · 2026-10-23（物理 / 分子机器 / 纳米机电）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-23.md</code> — 第42期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-physics</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（延续 10-21 起的确立做法，见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-23-电流驱动的分子机器——螺旋烯转子一转-电导反而更强" tabindex="-1">科学日报 2026-10-23：电流驱动的分子机器——螺旋烯转子一转，电导反而更强 <a class="header-anchor" href="#科学日报-2026-10-23-电流驱动的分子机器——螺旋烯转子一转-电导反而更强" aria-label="Permalink to &quot;科学日报 2026-10-23：电流驱动的分子机器——螺旋烯转子一转，电导反而更强&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-23.md</code> ｜ DOI: 10.1038/s41586-026-11312-x</p></blockquote><ul><li>原型：阿基米德螺旋（提水两千年、水轮机）的<strong>螺旋叶片结构</strong>同样出现在<strong>手性分子与纳米结构</strong>里，此前人们推测注入电流可产生力矩驱动其旋转。</li><li>实验：把一枚<strong>螺旋烯（helicene）分子</strong>悬在<strong>两根电极尖端之间</strong> —— 外加电压驱动分子做<strong>循环运动</strong>，<strong>方向偏好 100%</strong>，且可由<strong>电压极性反转</strong>。</li><li>关键观测（双效应）： <ul><li><strong>阈值之上电流显著增强</strong>：旋转让分子得以进入<strong>静止时够不到的「高导电构型」</strong>。</li><li><strong>增强起点可调</strong>：拉伸或压缩螺旋分子即可调节该阈值（此前的螺旋分子结未见此类效应，作者归因于结构与工作方式差异）。</li></ul></li><li>机制：计算表明<strong>电流诱导力驱动的分子旋转</strong>同时解释循环运动与电流增强，并预言在阈值电压处发生「<strong>逐步转动 → 连续转动</strong>」的转变。</li><li>结论：<strong>机械运动与电输运耦合</strong>，得到一个<strong>转子单方向性完美 + 电流可显著调制</strong>的力矩驱动分子机器原型。</li><li>洞察（对本库 <code>physics</code>）：本库「<strong>极限不是自然的属性，而是工具的属性</strong>」这一命题，在此表现为「<strong>把机械自由度接进电学读数</strong>」——以往分子机械（转动）与分子电子（导电）是两条线，本条把<strong>转动本身做成了一个可读的电学信号</strong>（电导随构型变化），且<strong>方向性来自结构手性而非外部驱动场</strong>。对照库内 10-13「芯片上光子量子斯格明子」（拓扑编码进结构）、10-21「螺旋位错把旋性写进晶体」：<strong>同族动作是「把功能编码进几何」</strong>，本条把这条线推到<strong>单分子尺度</strong>：几何＝一个可寻址的机械坐标，同时是电路的一部分。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/physics/index.md</code> ｜ 第42期 科学板块</p></blockquote><p>关键词：电流驱动分子机器、螺旋烯、helicene、分子转子、方向偏好100%、电压极性反转、旋转增强电导、阈值电压、逐步转动到连续转动、电流诱导力、分子结、纳米机电、机械自由度接进电学读数、功能编码进几何</p><p>关联：<code>topics/quantum-physics/science-daily-2026-10-23-quantum.md</code>、<code>topics/materials/science-daily-2026-10-23-materials.md</code>、<code>topics/physics/science-daily-2026-10-21-physics.md</code>、<code>topics/physics/index.md</code></p>',10)])])}const u=o(c,[["render",n]]);export{h as __pageData,u as default};
